function esc(value){return value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');}
function deepMerge(target, source){for(const [k,v] of Object.entries(source)){if(v&&typeof v==='object'&&!Array.isArray(v)){target[k]??={};deepMerge(target[k],v);}else target[k]=v;}return target;}
function setKey(html,key,value){const safe=key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const re=new RegExp(`(<([a-z][\\w-]*)\\b[^>]*\\bdata-i18n=["']${safe}["'][^>]*>)[\\s\\S]*?(</\\2>)`,'gi');const body=value.startsWith('html:')?value.slice(5):esc(value);return html.replace(re,(_,open,tag,close)=>`${open}${body}${close}`);}
function setMeta(html,title,description,route){const url=`https://camelotflows.dev${route}`;html=html.replace(/<title>[\s\S]*?<\/title>/i,`<title>${esc(title)}</title>`).replace(/<meta name="description" content="[^"]*">/i,`<meta name="description" content="${esc(description)}">`).replace(/<link rel="canonical" href="[^"]+">/i,`<link rel="canonical" href="${url}">`);html=html.replace(/(<meta property="og:title" content=")[^"]*(">)/i,`$1${esc(title)}$2`).replace(/(<meta property="og:description" content=")[^"]*(">)/i,`$1${esc(description)}$2`).replace(/(<meta property="og:url" content=")[^"]*(">)/i,`$1${url}$2`);return html;}
function applyMap(html,prefix,map){for(const [k,v] of Object.entries(map)){if(k.startsWith('meta_'))continue;html=setKey(html,`pages.${prefix}.${k}`,v);}return html;}
function routeFor(lang,route){return `${prefixes[lang]}${route}`||'/';}
function setAlternates(html,route){for(const lang of langs){const href=`https://camelotflows.dev${routeFor(lang,route)}`;html=html.replace(new RegExp(`(<link rel="alternate" hreflang="${lang}" href=")[^"]+(">)`,'i'),`$1${href}$2`);}return html.replace(/(<link rel="alternate" hreflang="x-default" href=")[^"]+(">)/i,`$1https://camelotflows.dev${route}$2`);}
function setServiceSchema(html,dict,route){const url=`https://camelotflows.dev${route}`;return html.replace(/(<script\b[^>]*type="application\/ld\+json"[^>]*>)([\s\S]*?)(<\/script>)/gi,(full,open,json,close)=>{try{const value=JSON.parse(json);if(value?.['@type']!=='Service')return full;value['@id']=`${url}#service`;value.url=url;value.name=dict.meta_title.replace(/\s*\|\s*Camelot Flows$/,'');value.description=dict.meta_description;value.provider={'@id':'https://camelotflows.dev/#organization'};value.areaServed=[{'@type':'Country',name:'Moldova'},{'@type':'Country',name:'Romania'}];value.inLanguage='en';return `${open}\n${JSON.stringify(value,null,2)}\n${close}`;}catch{return full;}});}
function setLanguageLinks(html,route){for(const lang of langs){html=html.replace(new RegExp(`(<a href=")[^"]+(" hreflang="${lang}")`,'g'),`$1${routeFor(lang,route)}$2`);}return html;}
function setNav(html,lang){const map={home:['/quote-to-order',nav[lang].home],services:['/industries/technical-distributors',nav[lang].services],arsenal:['/case-studies',nav[lang].arsenal],merlin:['/websites',nav[lang].merlin],cases:['/about',nav[lang].cases],contact:['/contact',nav[lang].contact],summon_agent:['/contact',nav[lang].summon_agent]};for(const [key,[route,label]] of Object.entries(map)){const re=new RegExp(`<a([^>]*?)href="[^"]*"([^>]*?data-i18n="common\\.nav\\.${key}"[^>]*)>[\\s\\S]*?<\\/a>`,'g');html=html.replace(re,`<a$1href="${routeFor(lang,route)}"$2>${esc(label)}</a>`);html=setKey(html,`common.nav.${key}`,label);}html=html.replace(/\s*<a[^>]*data-i18n="common\.nav\.(?:agencies|pricing)"[^>]*>[\s\S]*?<\/a>/g,'');return html;}
function setAnchorHref(html,key,route){const safe=key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const re=new RegExp(`<a([^>]*data-i18n="${safe}"[^>]*)>`,'g');return html.replace(re,(_,attrs)=>`<a${/\bhref=/.test(attrs)?attrs.replace(/href="[^"]*"/,`href="${route}"`):`${attrs} href="${route}"`}>`);}
function pageDictionary(values,lang){const [meta_title,meta_description,hero_eyebrow,hero_title,hero_lead,heroButton,c1,c2,c3,proc,out]=values;const fixed={en:['What the engagement covers.','Operational detail and boundaries.','Map one real workflow.','Share a non-confidential example. I will identify the useful first scope, approval points, exclusions, and failure states.'],ro:['Ce acoperă proiectul.','Detalii operaționale și limite.','Mapăm un flux real.','Trimite un exemplu neconfidențial. Voi identifica primul scop util, aprobările, excluderile și stările de eroare.'],ru:['Что охватывает проект.','Операционные детали и границы.','Разберём один реальный процесс.','Пришлите неконфиденциальный пример. Я определю полезный первый объём, одобрения, исключения и состояния сбоя.']}[lang];return {meta_title,meta_description,hero_eyebrow,hero_title,hero_lead,hero_btn_diagnostic:heroButton,hero_btn_brief:heroButton,s_del_h2:fixed[0],s_del_c1_h:c1[0],s_del_c1_p:c1[1],s_del_c2_h:c2[0],s_del_c2_p:c2[1],s_del_c3_h:c3[0],s_del_c3_p:c3[1],s_proc_h2:proc[0],s_proc_s1_name:proc[1],s_proc_s1_p:proc[2],s_proc_s2_name:proc[3],s_proc_s2_p:proc[4],s_proc_s3_name:proc[5],s_proc_s3_p:proc[6],s_proc_s4_name:proc[7],s_proc_s4_p:proc[8],s_out_h2:fixed[1],s_out_i1_h:out[0],s_out_i1_p:out[1],s_out_i2_h:out[2],s_out_i2_p:out[3],s_out_i3_h:out[4],s_out_i3_p:out[5],s_cta_h2:fixed[2],s_cta_p:fixed[3]};}

