for(const lang of langs){deepMerge(dictionaries[lang],{common:{nav:nav[lang]},pages:{index:home[lang],about:about[lang],'case-studies':cases[lang],contact:contactOverlay[lang]}});for(const [slug,set] of Object.entries(pageSets)){const pageKey=slug;dictionaries[lang].pages[pageKey]=pageDictionary(set[lang],lang);}}
