for(const [slug,map,file] of [['about',about,'about.html'],['contact',contactOverlay,'contact.html'],['case-studies',cases,'case-studies.html']])for(const lang of langs){const rel=lang==='en'?file:`${lang}/${file}`;let html=await readFile(path.join(root,rel),'utf8');html=applyMap(html,slug,map[lang]);html=setMeta(html,map[lang].meta_title,map[lang].meta_description,routeFor(lang,`/${file.replace('.html','')}`));html=setNav(html,lang);await writeFile(path.join(root,rel),html,'utf8');}

for(const [slug,set] of Object.entries(pageSets)){const pageKey=slug;const sourceTemplate=await readFile(path.join(root,`${set.template}.html`),'utf8');let html=sourceTemplate.replaceAll(`data-i18n-page="${set.template}"`,`data-i18n-page="${pageKey}"`).replaceAll(`pages.${set.template}.`,`pages.${pageKey}.`);const dict=dictionaries.en.pages[pageKey];html=applyMap(html,pageKey,dict);html=setMeta(html,dict.meta_title,dict.meta_description,set.route);html=setServiceSchema(html,dict,set.route);html=setAlternates(html,set.route);html=setLanguageLinks(html,set.route);html=setNav(html,'en');html=html.replaceAll(`https://camelotflows.dev/${set.template}`,`https://camelotflows.dev${set.route}`).replaceAll(`/${set.template}`,set.route).replace(/((?:src|href)=")assets\//g,'$1/assets/').replace(/((?:href)=")(?:favicon\.ico|favicon\.png|apple-touch-icon\.png)/g,(_,start)=>`${start}/${_.slice(start.length)}`);const out=slug==='technical-distributors'?'industries/technical-distributors.html':slug==='hvac-refrigeration'?'industries/hvac-refrigeration.html':`${slug}.html`;await mkdir(path.dirname(path.join(root,out)),{recursive:true});await writeFile(path.join(root,out),html,'utf8');}

